import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

// Network Base Endpoint Configuration matching your system standards
const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

// ─── SYSTEM ID & SECTION TRANSLATION DICTIONARY ───
// Maps raw telemetry keys to clean, non-confusing section blocks
const zoneLocationMapping = {
  "Node1_Zone_Demand": {
    sectionTitle: "SECTION 1",
    label: "Zone ID: Node 1",
    color: "#dc2626" // Red accent line
  },
  "Node2_Zone_Demand": {
    sectionTitle: "SECTION 2",
    label: "Zone ID: Node 2",
    color: "#0284c7" // Blue accent line
  },
  "Node5_Zone_Demand": {
    sectionTitle: "SECTION 3",
    label: "Zone ID: Node 5",
    color: "#16a34a" // Green accent line
  },
  "Node7_Zone_Demand": {
    sectionTitle: "SECTION 4",
    label: "Zone ID: Node 7",
    color: "#ea580c" // Orange accent line
  }
};

const DemandForecasting = () => {
  const navigate = useNavigate();
  const [forecastData, setForecastData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch telemetry function block
  const fetchLiveDemandData = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/weather/water-demand`);      
      if (!response.ok) {
        throw new Error(`Server returned status: ${response.status}`);
      }
      const result = await response.json();
      if (result.success) {
        setForecastData(result);
        setError(null);
      } else {
        throw new Error(result.error || 'Failed parsing live data arrays.');
      }
    } catch (err) {
      console.error('Error connecting to hydraulic telemetry stream:', err);
      setError(err.message || 'Failed connecting to real-time S3 telemetry streams.');
    } finally {
      setLoading(false);
    }
  };

  // Setup Lifecycle Polling Loop Hooks
  useEffect(() => {
    fetchLiveDemandData();

    // Establish dynamic background update polling loop execution cycle every 30 seconds
    const telemetryInterval = setInterval(fetchLiveDemandData, 30000);
    return () => clearInterval(telemetryInterval);
  }, []);

  return (
    <div className="demand-forecasting-container" style={{ padding: '24px', fontFamily: '"Segoe UI", Roboto, sans-serif', maxWidth: '1280px', margin: '0 auto', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      
      {/* Back to Weather Dashboard */}
      <button 
        className="btn btn-secondary" 
        onClick={() => navigate('/weather-home')}
        style={{ marginBottom: '24px', cursor: 'pointer', padding: '10px 18px', borderRadius: '6px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '8px', color: '#334155', boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}
      >
        <i className="fas fa-arrow-left"></i> Back to Weather Homepage
      </button>

      <header style={{ borderBottom: '2px solid #e2e8f0', paddingBottom: '20px', marginBottom: '32px' }}>
        <h1 style={{ color: '#0f172a', margin: '0 0 8px 0', fontSize: '28px', fontWeight: '700' }}>Real-time Hydraulic Demand Forecasting</h1>
        <p style={{ color: '#475569', margin: '0', fontSize: '16px' }}>
          Live operational data from the Artificial Intelligence Integrated Water Distribution system bed.
        </p>
      </header>

      {/* Asynchronous System Handling Interceptors */}
      {loading ? (
        <div style={{ padding: '60px', textAlign: 'center', color: '#64748b' }}>
          <div style={{ width: '36px', height: '36px', border: '3px solid #e2e8f0', borderTop: '3px solid #0284c7', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 16px auto' }}></div>
          <p style={{ fontSize: '15px' }}>Connecting to AWS S3 telemetry buffers...</p>
          <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
        </div>
      ) : error ? (
        <div style={{ padding: '24px', background: '#fef2f2', border: '1px solid #fee2e2', borderRadius: '8px', color: '#991b1b', marginBottom: '24px' }}>
          <h4 style={{ margin: '0 0 8px 0', display: 'flex', alignItems: 'center', gap: '8px' }}><i className="fas fa-exclamation-triangle"></i> Operational Telemetry Offline</h4>
          <p style={{ margin: '5px 0 15px 0', fontSize: '14px' }}>{error}</p>
          <button onClick={fetchLiveDemandData} style={{ padding: '8px 16px', backgroundColor: '#991b1b', color: '#ffffff', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: '500' }}>
            Retry Telemetry Fetch
          </button>
        </div>
      ) : (
        <>
          {/* Real-time Content Display Block */}
          <div style={{ background: '#ffffff', borderRadius: '10px', border: '1px solid #e2e8f0', padding: '24px', marginBottom: '32px', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', marginBottom: '24px', gap: '16px', borderBottom: '1px solid #f1f5f9', paddingBottom: '16px' }}>
              <h3 style={{ margin: '0', color: '#334155', fontSize: '16px', fontWeight: '600' }}>
                <i className="fas fa-satellite-dish" style={{ marginRight: '8px', color: '#10b981' }}></i>
                Live Forecast Execution Cycle: <span style={{ fontWeight: 'normal', color: '#64748b' }}>{forecastData?.timestamp}</span>
              </h3>
              <span style={{ fontSize: '12px', background: '#d1fae5', color: '#065f46', padding: '6px 14px', borderRadius: '30px', fontWeight: '600' }}>
                <i className="fas fa-sync-alt fa-spin" style={{ marginRight: '6px' }}></i> Auto-refreshing Live from S3
              </span>
            </div>

            {/* Demand Metrics Grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '24px' }}>
              {forecastData?.demand && Object.keys(forecastData.demand).length > 0 ? (
                Object.entries(forecastData.demand).map(([nodeName, val]) => {
                  // Fallback dictionary map defaults if an unrecognized node payload passes through
                  const systemSegment = zoneLocationMapping[nodeName] || {
                    sectionTitle: "SYSTEM NODE",
                    label: `ID: ${nodeName.replace(/_/g, ' ')}`,
                    color: "#64748b"
                  };

                  return (
                    <div 
                      key={nodeName} 
                      style={{ 
                        background: '#ffffff', 
                        padding: '24px', 
                        borderRadius: '12px', 
                        border: '1px solid #e2e8f0', 
                        borderTop: `5px solid ${systemSegment.color}`, 
                        boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)' 
                      }}
                    >
                      <h4 style={{ margin: '0 0 4px 0', color: '#0f172a', fontSize: '18px', fontWeight: '700' }}>
                        {systemSegment.sectionTitle}
                      </h4>
                      <span style={{ fontSize: '13px', color: '#64748b', fontWeight: '500', display: 'block', marginBottom: '16px' }}>
                        {systemSegment.label}
                      </span>
                      
                      <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px', borderTop: '1px solid #f1f5f9', paddingTop: '16px' }}>
                        <p style={{ fontSize: '36px', fontWeight: '800', margin: '0', color: '#0f172a', letterSpacing: '-0.5px' }}>
                          {val}
                        </p>
                        <span style={{ fontSize: '16px', color: '#475569', fontWeight: '600' }}>m³/h</span>
                      </div>
                    </div>
                  );
                })
              ) : (
                <p style={{ color: '#64748b', gridColumn: '1/-1', textAlign: 'center', padding: '20px' }}>No node matrices populated for this parsing sequence.</p>
              )}
            </div>
          </div>

          {/* Infrastructure Intent Explainer Block */}
          <div style={{ background: '#eff6ff', border: '1px solid #bfdbfe', borderRadius: '8px', padding: '24px' }}>
            <h4 style={{ margin: '0 0 8px 0', color: '#1e40af', fontSize: '16px', fontWeight: '600' }}>
              <i className="fas fa-info-circle" style={{ marginRight: '8px' }}></i> Active Stakeholder Network Coordination
            </h4>
            <p style={{ margin: '0', color: '#1e3a8a', lineHeight: '1.6', fontSize: '14.5px' }}>
              This portal streams calculated pipeline demand matrices directly from your edge telemetry network. The platform correlates hydraulic data with dynamic regional factors to automatically optimize valve distribution patterns.
            </p>
          </div>
        </>
      )}
    </div>
  );
};

export default DemandForecasting;
